def check_order(base, modulus):
    order = 1
    while True:
        if pow(base, order, modulus) == 1:
            return order
        order += 1

# Modulus is 10000
k = check_order(3, 10000)
print(f"Order k: {k}")

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def order_mod(base, modulus):
    if gcd(base, modulus) != 1:
        return None
    phi = modulus - modulus // base if base == 1 else modulus # Using Euler's totient function for general modulus might be tricky, let's just check powers.

    # Since 10000 is relatively small, we can iterate up to phi(10000) = 4000
    # phi(10000) = 10000 * (1 - 1/2) * (1 - 1/5) = 10000 * 1/2 * 4/5 = 4000.

    from sympy import totient
    if modulus == 10000:
        phi = 4000
    else:
        phi = totient(modulus)

    # Check divisors of phi(modulus)
    divisors = []
    for i in range(1, int(phi**0.5) + 1):
        if phi % i == 0:
            divisors.append(i)
            divisors.append(phi // i)
    divisors = sorted(list(set(d for d in divisors if d >= 1)))

    for k in divisors:
        if pow(base, k, modulus) == 1:
            return k
    return phi # Should not happen if the list is complete

k0 = order_mod(3, 10000)
print(f"k0 = {k0}")
